import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, DoubleSide } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Journal', role: 'headline', typography: { fontSize: 96, weight: 400 } },
    ];

  const root = new Group();
  root.name = 'journal-title';

  // --- floating accent sprite (atlas region 512x320) ---
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const accentHeight = 0.7;
  const accentWidth = accentHeight * aspect;

  const accentGeo = new PlaneGeometry(accentWidth, accentHeight, 1, 1);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  accentMat.colorNode = vec3(1, 1, 1);
  accentMat.opacityNode = uniform(0.0);

  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-1.35, 0.02, -0.05);
  accentMesh.renderOrder = 0;
  root.add(accentMesh);

  const accentTintUniform = uniform(0.15);

  let disposed = false;
  const texPromise = ctx.textureLoader.loadTexture(
    config.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png'
  );
  texPromise.then((tex) => {
    if (disposed) return;
    tex.colorSpace = THREE.SRGBColorSpace;
    const texNode = texture(tex, uv());
    const accentColor = vec3(
      parseInt(colors.accent.slice(1, 3), 16) / 255,
      parseInt(colors.accent.slice(3, 5), 16) / 255,
      parseInt(colors.accent.slice(5, 7), 16) / 255
    );
    accentMat.colorNode = mix(texNode.rgb, accentColor, accentTintUniform);
    accentMat.opacityNode = texNode.a;
    accentMat.needsUpdate = true;

    gsap.to(accentMesh.material, {
      duration: 0.01,
      onStart: () => {
        // fade in the accent alongside text (handled by fadeTl below via material uniform proxy)
      },
    });
  });

  // --- headline text: "Journal" ---
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Journal' };
  const fontSize = headlineItem.typography?.fontSize ?? 96;

  const headline = ctx.fontAtlas.createText(headlineItem.text ?? 'Journal', {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  headline.position.set(0.3, 0, 0);
  root.add(headline);

  // --- entrance: weighted-settle rise-in, translate <=0.4 units ---
  root.position.y -= 0.35;
  root.scale.setScalar(0.98);
  const accentOpacityDriver = { fade: 0 };

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: root.position.y + 0.35,
    duration: 0.75,
    ease: 'power3.out',
  }, 0);
  tl.to(root.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.45,
    ease: 'power2.out',
  }, 0);
  tl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.45);
  tl.to(accentOpacityDriver, {
    fade: 1,
    duration: 0.6,
    ease: 'power2.out',
    onUpdate: () => {
      accentMesh.visible = accentOpacityDriver.fade > 0.01;
    },
  }, 0.1);

  // --- idle breathing (<=2%) on the accent only, subtle ---
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(accentMesh.scale, {
    x: 1.02,
    y: 1.02,
    duration: 2.4,
    ease: 'sine.inOut',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    idleTl.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(accentMesh.scale);
    gsap.killTweensOf(accentOpacityDriver);

    accentGeo.dispose();
    accentMat.dispose();

    if (headline?.geometry) headline.geometry.dispose();
    if (headline?.material) {
      const mats = Array.isArray(headline.material) ? headline.material : [headline.material];
      mats.forEach((m) => m?.dispose?.());
    }
  };

  return root;
}
